// ?setPriority@AttackPriorityInfo@@QAEXPBVThingTemplate@@H@Z
// partial score=0.9041 date=2026-09-29
//
// Identity: AttackPriorityInfo::setPriority(const ThingTemplate *, Int).
// Proven by the ILT pin at 0x0001600E (pin_consistency: consistent) and by
// the five matched callers, including the byte-matched
// AttackPriorityInfo::xfer at 0x0034EDA0 which calls
// `setPriority(thingTemplate, priority)`. See
// targets/game/reverse/identity_evidence/0034ece0-attackpriorityinfo-setpriority.md
//
// 146/146 bytes EXACT SIZE, 132/146 byte-equal = 0.9041, 8 relocations.
// This is the first source in 12 attempts to reach retail's 146-byte length;
// every earlier attempt produced 145 with a `push ecx` frame slot and the
// alternate `push -1 / push handler / mov eax,fs:[0]` SEH prologue.
//
// THREE shape facts, each an earlier blocker, all now applied:
//
// 1. The `thing` parameter is NEVER assigned. It is loaded once into EDI and
//    stays there. Assigning to it (any `thing = ...` spelling) makes MSVC
//    treat it as a memory variable, which costs a frame slot and flips the
//    SEH prologue order. Measured: `thing = n ? A() : thing` -> 145 with the
//    wrong prologue. The key is a SEPARATE variable.
//
// 2. `key` is declared in its own `{ }` block AFTER the lazy allocation.
//    At function scope it costs a real frame slot (149). In the inner block
//    MSVC places it in the DEAD `thing` argument home at [esp+0x18], reusing
//    the slot the new-expression pointer already used -- exactly what retail
//    does at +0x32 and +0x6b.
//
// 3. `key` is initialised to `thing` and then conditionally OVERWRITTEN
//    (`if (n) key = ...`), not built by a `?:`. The `?:` and the
//    if/else-both-arms forms both give 148 with the store duplicated per arm.
//
// RESIDUE (14 bytes, one phi). Retail merges the override resolution into
// EAX and stores once:
//       call getFinalOverride / jmp / mov eax,edi / mov [esp+0x18],eax
// This source stores the initial `key = thing` before the branch and the
// override result inside it:
//       mov [esp+0x18],edi / je / call / mov [esp+0x18],eax
// Same length, same frame, same register allocation, same relocation
// layout; only the merge point differs. Getting MSVC 7.1 to sink the
// pre-branch store into a phi needs a spelling that keeps `key` in a
// register across the branch, which every tried form defeats by needing the
// address of `key` for the map subscript.
typedef int Int;

class Overridable
{
public:
	Overridable *getFinalOverride();

	void *m_vtable;
	Overridable *m_nextOverride;
};

class ThingTemplate : public Overridable
{
};

class AttackPriorityMap
{
public:
	AttackPriorityMap();
	Int &operator[](const ThingTemplate *const &thing);

private:
	char m_padding[0x0c];
};

class AttackPriorityInfo
{
public:
	void setPriority(const ThingTemplate *thing, Int priority);

private:
	char m_prefix[0x0c];
	AttackPriorityMap *m_priorityMap;
};

void AttackPriorityInfo::setPriority(const ThingTemplate *thing, Int priority)
{
	if (thing == 0)
		return;

	if (m_priorityMap == 0)
		m_priorityMap = new AttackPriorityMap;

	{
		Overridable *n = ((ThingTemplate *)thing)->m_nextOverride;
		const ThingTemplate *key = thing;
		if (n != 0)
			key = (const ThingTemplate *)n->getFinalOverride();
		(*m_priorityMap)[key] = priority;
	}
}
